using UnityEngine;
using UnityEditor;
using System;
using System.IO;
using System.Text;
using ConRoi.Investigation.V36.R103;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            s.OpenPage("reconstruction");
            s.ResetTrial();
            var w = EditorWindow.GetWindow(Type.GetType("UnityEditor.GameView,UnityEditor"));
            int i = 0;
            double next = EditorApplication.timeSinceStartup + 1;
            var log = new StringBuilder();
            EditorApplication.CallbackFunction f = null;
            f = () =>
            {
                if (EditorApplication.timeSinceStartup < next)
                    return;
                next = EditorApplication.timeSinceStartup + 1;
                log.AppendLine("after " + (i - 1) + " id=" + s.TrialId + " t=" + s.TrialTime);
                if (i == 5)
                {
                    EditorApplication.update -= f;
                    File.WriteAllText("Test/KetQua/investigation_r103/click-probe.txt", log.ToString());
                    return;
                }

                s.ResetTrial();
                Vector2 p = i == 0 ? new Vector2(400, 142) : i == 1 ? new Vector2(400, 170) : i == 2 ? new Vector2(500, 170) : i == 3 ? new Vector2(500, 152) : new Vector2(400, 121);
                w.SendEvent(new Event{type = EventType.MouseDown, button = 0, mousePosition = p});
                w.SendEvent(new Event{type = EventType.MouseUp, button = 0, mousePosition = p});
                log.AppendLine("click " + i + " " + p);
                i++;
            };
            EditorApplication.update += f;
            r.Log("Five bounded coordinate probes; test UI events only");
        }
    }
}

